CREATE TABLE "public"."agent_memory" (
  "memory_id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "user_id"           uuid                     NOT NULL,
  "memory_type"       text                     NOT NULL,
  "content"           jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "relevance"         double precision         DEFAULT 1.0,
  "source_session_id" uuid,
  "created_at"        timestamp with time zone DEFAULT now(),
  "expires_at"        timestamp with time zone,
  CONSTRAINT "agent_memory_memory_type_check" CHECK ((memory_type = ANY (ARRAY['session'::text, 'long_term'::text, 'preference'::text, 'flashcard'::text]))),
  CONSTRAINT "agent_memory_pkey" PRIMARY KEY (memory_id)
);

