COMMENT ON TABLE "public"."review_schedule" IS 'Agent-proposed spaced review. Read by the Background Learning Coach when due.';

COMMENT ON TABLE "public"."user_learning_profile" IS 'Global learning stats per user — consumed by Planner agent';

